function migrateOldScratchpads(){let changed=false;const oldSat=localGet('studyspace_sat_scratchpad'),oldJee=localGet('studyspace_jee_scratchpad');if(oldSat&&!subjectNotes['SAT Math']){subjectNotes['SAT Math']=`Imported from the earlier SAT scratchpad. Move any English notes to SAT English when you review them.\n\n${oldSat}`;changed=true}if(oldJee&&!subjectNotes['JEE Math']){subjectNotes['JEE Math']=`Imported from the earlier JEE scratchpad. Move any Chemistry or Physics notes to their own subject when you review them.\n\n${oldJee}`;changed=true}if(changed)localSet('studyspace_subject_notes',JSON.stringify(subjectNotes))}
