function initStudyViews(){const titles={overview:'Overview',sat:'SAT',jee:'JEE',college:'College',other:'Other studies',library:'Notes & formulas',planner:'Timetable',exams:'Exams',groups:'Study group',history:'Study log'};const open=view=>setStudyView(view);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>open(b.dataset.view));document.querySelectorAll('[data-open-view]').forEach(b=>b.onclick=()=>open(b.dataset.openView));document.querySelectorAll('[data-open-subject]').forEach(b=>b.onclick=()=>{librarySubject=b.dataset.openSubject;libraryTrack=trackForSubject(librarySubject);open('library');renderLibrary()});document.querySelectorAll('[data-library-track]').forEach(b=>b.onclick=()=>{libraryTrack=b.dataset.libraryTrack;librarySubject=TRACK_SUBJECTS[libraryTrack][0];renderLibrary()});$('formulaSearch').oninput=renderFormulaList;const requested=new URLSearchParams(location.search).get('view');setStudyView(titles[requested]?requested:'overview',false);window.addEventListener('popstate',()=>{const v=new URLSearchParams(location.search).get('view');setStudyView(titles[v]?v:'overview',false)})}
