function initThemeSwitch(){const valid=['light','dark','system'],apply=(mode,save=true)=>{if(!valid.includes(mode))mode='system';const resolved=mode==='system'?(window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light'):mode;document.documentElement.dataset.themeMode=mode;document.body.dataset.themeMode=mode;document.documentElement.dataset.colorScheme=resolved;document.body.dataset.colorScheme=resolved;document.documentElement.style.colorScheme=resolved;const index=valid.indexOf(mode);$('themeSwitch').style.setProperty('--theme-index',index);document.querySelectorAll('[data-theme-mode]').forEach(b=>{const active=b.dataset.themeMode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});$('themeModeLabel').textContent=`${mode[0].toUpperCase()+mode.slice(1)} theme`;if(save)localSet('studyspace_theme_mode',mode)};document.querySelectorAll('[data-theme-mode]').forEach(b=>b.onclick=()=>apply(b.dataset.themeMode));window.applyStudyspaceTheme=apply;window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if((document.body.dataset.themeMode||'system')==='system')apply('system',false)});apply(localGet('studyspace_theme_mode')||'system',false)}
