function renderFormulaList(){const groups=window.STUDYSPACE_FORMULAS?.[librarySubject]||[];const q=$('formulaSearch').value.trim().toLowerCase();$('formulaScope').textContent=groups.length?`${librarySubject} · ${groups.reduce((n,g)=>n+g[1].length,0)} quick references`:`${librarySubject} · no standard formula sheet for this subject`;const found=groups.map(([topic,items])=>[topic,items.filter(([name,formula])=>!q||`${name} ${formula} ${topic}`.toLowerCase().includes(q))]).filter(([,items])=>items.length);$('formulaList').innerHTML=found.length?found.map(([topic,items])=>`<section class="formula-group"><h4>${escapeHtml(topic)}</h4>${items.map(([name,formula])=>`<div class="formula-row"><b>${escapeHtml(name)}</b><code>${escapeHtml(formula)}</code></div>`).join('')}</section>`).join(''):'<div class="empty">No matching formulas for this subject. Try another search or choose another subject.</div>'}
