function initExams(){$('examForm').onsubmit=e=>{e.preventDefault();const name=$('examNameInput').value.trim(),date=$('examDateInput').value;if(!name||!date)return;examRows.push({name,date,id:crypto.randomUUID?.()||String(Date.now())});saveExams();$('examForm').reset();$('examDateInput').min=isoNow();renderExamDashboard();renderExamList()};$('examTimerStart').onclick=toggleExamTimer;$('examTimerReset').onclick=resetExamTimer;['examTimerHours','examTimerMinutes'].forEach(id=>$(id).oninput=()=>{if(!examTimer?.running)updateExamClock()});updateExamClock()}
