function nextExam(){const today=isoNow();return [...examRows].filter(x=>x.date>=today).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
function countdownFor(date){const today=isoNow();if(date===today)return{short:'Today',full:'It’s exam day. Good luck!'};if(date<today){const a=new Date(`${date}T12:00:00`),b=new Date(`${today}T12:00:00`),days=Math.round((b-a)/86400000);return{short:`Passed ${days} day${days===1?'':'s'} ago`,full:'This exam date has passed. You can still keep it in your exam list.'}}const target=new Date(`${date}T00:00:00`).getTime(),delta=target-Date.now(),days=Math.floor(delta/86400000),hours=Math.floor(delta%86400000/3600000),minutes=Math.floor(delta%3600000/60000),seconds=Math.floor(delta%60000/1000);return{short:`${days}d ${String(hours).padStart(2,'0')}h ${String(minutes).padStart(2,'0')}m`,full:`${days} days, ${hours} hours, ${minutes} minutes, ${seconds} seconds left`}}
function renderExamDashboard(){const exam=nextExam()||[...examRows].sort((a,b)=>b.date.localeCompare(a.date))[0];const name=exam?exam.name:'Add an exam date';const countdown=exam?countdownFor(exam.date):null;const text=countdown?.full||(examRows.length?'All your saved exam dates have passed. Add an upcoming date anytime.':'Choose a date and it will count down here.');$('nextExamName').textContent=name;$('nextExamCountdown').textContent=countdown?.short||text;$('nextExamNameFull').textContent=exam?`${exam.name} · ${new Date(`${exam.date}T12:00:00`).toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}`:'No exam added yet';$('nextExamCountdownFull').textContent=text;$('nextExamDays').textContent=countdown?.short||'—'}
function renderExamList(){if(!$('examList'))return;const rows=[...examRows].sort((a,b)=>a.date.localeCompare(b.date));$('examCount').textContent=`${rows.length} EXAM${rows.length===1?'':'S'}`;$('examList').innerHTML=rows.length?rows.map(x=>{const c=countdownFor(x.date);return`<article class="exam-row"><div><b>${escapeHtml(x.name)}</b><small>${new Date(`${x.date}T12:00:00`).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</small></div><span class="exam-countdown">${escapeHtml(c.short)}</span><button class="del-btn" data-remove-exam="${escapeHtml(x.id)}" aria-label="Remove ${escapeHtml(x.name)}">×</button></article>`}).join(''):'<div class="empty">No exams yet. Add a date above to start your countdown.</div>';document.querySelectorAll('[data-remove-exam]').forEach(b=>b.onclick=()=>{examRows=examRows.filter(x=>x.id!==b.dataset.removeExam);saveExams();renderExamDashboard();renderExamList()})}
function examRemaining(){if(!examTimer)return 0;return examTimer.running?Math.max(0,Math.ceil((examTimer.endsAt-Date.now())/1000)):Math.max(0,examTimer.remainingSeconds||0)}
function updateExamClock(){const remaining=examRemaining();const display=examTimer?.running||examTimer?.remainingSeconds!==undefined?remaining:Math.max(0,(+$('examTimerHours').value||0)*3600+(+$('examTimerMinutes').value||0)*60);$('examClock').textContent=displayClock(display);if(examTimer?.running&&remaining===0){examTimer={...examTimer,running:false,remainingSeconds:0};localSet('studyspace_exam_timer',JSON.stringify(examTimer));$('examTimerStatus').textContent='Time is up. Nice work finishing your practice block.';$('examTimerStart').textContent='Start exam timer';return}if(examTimer?.running){$('examTimerStart').textContent='Pause timer';$('examTimerStatus').textContent='Practice timer is running.'}else if(examTimer?.remainingSeconds>0){$('examTimerStart').textContent='Resume timer';$('examTimerStatus').textContent='Timer paused. Your remaining time is saved.'}else{$('examTimerStart').textContent='Start exam timer';if(!$('examTimerStatus').textContent||$('examTimerStatus').textContent==='Practice timer is running.')$('examTimerStatus').textContent='Set a duration, then start when your practice begins.'}}
function toggleExamTimer(){if(examTimer?.running){const left=examRemaining();examTimer={...examTimer,running:false,remainingSeconds:left};localSet('studyspace_exam_timer',JSON.stringify(examTimer));updateExamClock();return}let total=examTimer?.remainingSeconds>0?examTimer.remainingSeconds:(+$('examTimerHours').value||0)*3600+(+$('examTimerMinutes').value||0)*60;if(total<=0){$('examTimerStatus').textContent='Set at least one minute first.';return}examTimer={totalSeconds:total,remainingSeconds:total,endsAt:Date.now()+total*1000,running:true};localSet('studyspace_exam_timer',JSON.stringify(examTimer));updateExamClock()}
