  $('memberList').innerHTML=roster.length?roster.map(m=>{const p=presenceFor(m.id),mode=p?.mode||'offline',baseStudy=p?.studySeconds||0,baseBreak=p?.breakSeconds||0,elapsed=p?.stateSince?Math.max(0,Math.floor((Date.now()-p.stateSince)/1000)):0,study=baseStudy+(mode==='study'?elapsed:0),breakTime=baseBreak+(mode==='break'?elapsed:0),detail=mode==='study'?`Studying · ${escapeHtml(p.subject||'Study session')} · ${displayClock(study)}`:mode==='break'?`On break · ${displayClock(breakTime)}`:mode==='idle'?'Online · not studying':'Offline';return `<div class="member-card"><span class="member-avatar ${p?'online':''}">${escapeHtml(m.name.slice(0,1).toUpperCase())}</span><div class="member-main"><b>${escapeHtml(m.name)}${m.id===currentUser?.id?' (you)':''}</b><small>${detail}</small></div><span class="member-state ${mode}">${mode==='study'?'STUDYING':mode==='break'?'BREAK':mode==='idle'?'ONLINE':'OFFLINE'}</span>${owner&&m.id!==currentUser?.id?`<button class="member-remove" data-remove-member="${m.id}" title="Remove from group">×</button>`:''}</div>`}).join(''):'<div class="empty">Your group roster will appear here.</div>';
  document.querySelectorAll('[data-remove-member]').forEach(button=>button.onclick=async()=>{const member=roster.find(m=>m.id===button.dataset.removeMember);if(!member||!confirm(`Remove ${member.name} from this group?`))return;const {error}=await supabaseClient.from('group_members').delete().eq('group_id',activeGroupId).eq('user_id',member.id);if(error)groupStatus(error.message,'error');else{groupStatus(`${member.name} was removed from the group.`,'success');await loadGroupMembers()}});
