  const result=await groupChannel.track({user_id:currentUser.id,display_name:currentProfile?.display_name||'Student',mode,subject:shared?activeTimer.subject:'',studySeconds:shared?activeTimer.studySeconds:0,breakSeconds:shared?activeTimer.breakSeconds:0,stateSince:shared?activeTimer.stateSince:null,updatedAt:Date.now()});if(result!=='ok')groupStatus('Could not publish live status. Check the private presence policies.','error');renderGroupMembers();
